&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;R&#232;gles mythiques&lt;a class=&quot;headeranchor&quot; id=&quot;R&#232;gles_mythiques_0&quot; href=&quot;#R&#232;gles_mythiques_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-Mythiques.html&quot; title=&quot;Pr&#233;sentation des r&#232;gles mythiques&quot;&gt;Pr&#233;sentation&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique.html&quot; title=&quot;Glossaire mythique&quot;&gt;glossaire mythique&lt;/a&gt;)&lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton1&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;1&#39;);&quot; onmouseout=&quot;outButton(&#39;1&#39;);&quot; onclick=&quot;expandMenu(&#39;1&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mener-Une-Partie-Mythique.html&quot; title=&quot;Mener une partie mythique&quot;&gt;Mener une partie mythique&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;1&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Structure-Du-R&#233;cit-Mythique.html&quot; title=&quot;La structure du r&#233;cit mythique&quot;&gt;La structure du r&#233;cit mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Th&#232;mes-Mythiques.html&quot; title=&quot;Les th&#232;mes mythiques&quot;&gt;Les th&#232;mes mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Conception-Des-Rencontres-Mythiques.html&quot; title=&quot;Conception des rencontres mythiques&quot;&gt;La conception des rencontres mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;preuves-Mythiques.html&quot; title=&quot;Les &#233;preuves mythiques&quot;&gt;Les &#233;preuves mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faveurs-Mythiques.html&quot; title=&quot;Les faveurs mythiques&quot;&gt;Les faveurs mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sc&#233;l&#233;rats-Mythiques-R&#233;currents.html&quot; title=&quot;Sc&#233;l&#233;rats mythiques r&#233;currents&quot;&gt;Les sc&#233;l&#233;rats mythiques r&#233;currents&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fauts-Mythiques.html&quot; title=&quot;Les d&#233;fauts mythiques&quot;&gt;Les d&#233;fauts mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Id&#233;es-Daventures-Mythiques.html&quot; title=&quot;Id&#233;es d&amp;#39;aventures mythiques&quot;&gt;Id&#233;es d’aventures mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton2&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;2&#39;);&quot; onmouseout=&quot;outButton(&#39;2&#39;);&quot; onclick=&quot;expandMenu(&#39;2&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-Personnage-Mythique.html&quot; title=&quot;Cr&#233;ation d&amp;#39;un personnage mythique&quot;&gt;Cr&#233;ation d&#39;un personnage mythique&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;2&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;Voie de l&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Archimage-Mythique.html&quot; title=&quot;L&amp;#39;archimage mythique&quot;&gt;archimage&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-Voie-De-Larchimage-Mythique.html&quot; title=&quot;Aptitudes de voie de l&amp;#39;archimage mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Champion-Mythique.html&quot; title=&quot;Le champion mythique&quot;&gt;champion&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Champion-Mythique.html&quot; title=&quot;Aptitudes de voie du champion mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Filou-Mythique.html&quot; title=&quot;Le filou mythique&quot;&gt;filou&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Filou-Mythique.html&quot; title=&quot;Aptitudes de voie du filou mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Hi&#233;rophante-Mythique.html&quot; title=&quot;Le hi&#233;rophante mythique&quot;&gt;hi&#233;rophante&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Hi&#233;rophante-Mythique.html&quot; title=&quot;Aptitudes de voie du hi&#233;rophante mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Mar&#233;chal-Mythique.html&quot; title=&quot;Le mar&#233;chal mythique&quot;&gt;mar&#233;chal&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Mar&#233;chal-Mythique.html&quot; title=&quot;Aptitudes de voie du mar&#233;chal mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;Voie du &lt;a class=&quot;pagelink&quot; href=&quot;Protecteur-Mythique.html&quot; title=&quot;Le protecteur mythique&quot;&gt;protecteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Du-Protecteur-Mythique.html&quot; title=&quot;Aptitudes de voie du protecteur mythique&quot;&gt;aptitudes&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-Voie-Universelles-Mythique.html&quot; title=&quot;Aptitudes de voie universelles Mythique&quot;&gt;Aptitudes de voie universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-La-Voie-Des-Enfants-Divins-Mythiques.html&quot; title=&quot;Aptitudes de voie des enfants divins mythiques&quot;&gt;Aptitudes de voie des enfants divins&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton3&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;3&#39;);&quot; onmouseout=&quot;outButton(&#39;3&#39;);&quot; onclick=&quot;expandMenu(&#39;3&#39;);&quot; /&gt;
&lt;/div&gt;Options de personnage mythiques&amp;emsp;
        &lt;ul ID=&quot;3&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dons-Mythiques.html&quot; title=&quot;Les dons mythiques&quot;&gt;Les dons mythiques&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Dons-Mythiques.html&quot; title=&quot;Dons mythiques&quot;&gt;tableau&lt;/a&gt;)&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-L&#233;gendaires.html&quot; title=&quot;Objets l&#233;gendaires&quot;&gt;Les objets l&#233;gendaires&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Objets-Magiques-Mythiques.html&quot; title=&quot;Les objets magiques mythiques&quot;&gt;Les objets magiques mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorts-Mythiques.html&quot; title=&quot;Les sorts mythiques&quot;&gt;Les sorts mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
    &lt;li&gt;&lt;div style=&quot;float: right; padding: 0;&quot;&gt;
&lt;IMG id=&quot;bouton4&quot; src=&quot;/images/pathfinder/wiki/BoutonP.jpg&quot; style=&quot;float:right; width: 10px; border: 1px solid black; cursor: pointer&quot; onmouseover=&quot;overButton(&#39;4&#39;);&quot; onmouseout=&quot;outButton(&#39;4&#39;);&quot; onclick=&quot;expandMenu(&#39;4&#39;);&quot; /&gt;
&lt;/div&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monstres-Mythiques.html&quot; title=&quot;Les monstres mythiques&quot;&gt;Les monstres mythiques&lt;/a&gt;&amp;emsp;
        &lt;ul ID=&quot;4&quot; CLASS=&quot;listecach&#233;e cadrebas&quot;&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arch&#233;types-Simples-De-Cr&#233;atures-Mythiques.html&quot; title=&quot;Arch&#233;types simples de cr&#233;atures mythiques&quot;&gt;Arch&#233;types simples de cr&#233;atures mythiques&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Construire-Une-Cr&#233;ature-Mythique.html&quot; title=&quot;Construire une cr&#233;ature mythique&quot;&gt;Construire une cr&#233;ature mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-Mythique.html&quot; title=&quot;Mythique (sous-type)&quot;&gt;Le sous-type mythique&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#232;gles-De-Monstres-Mythiques-Universelles.html&quot; title=&quot;R&#232;gles de monstres mythiques universelles&quot;&gt;R&#232;gles de monstres mythiques universelles&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;valuer-Les-Statistiques-Des-Monstres.html&quot; title=&quot;&#201;valuer les statistiques des monstres&quot;&gt;&#201;valuer les statistiques des monstres&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Liste-Alphab&#233;tique-Des-Monstres-Mythiques.html&quot; title=&quot;Liste alphab&#233;tique des monstres mythiques&quot;&gt;Liste des monstres mythiques&lt;/a&gt;&lt;/li&gt;
        &lt;/ul&gt;
    &lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Campagnes mythiques (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Mythic Adventures, Mythic Origins/Campagnes mythiques&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoCMy.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Les sorts mythiques puisent dans le pouvoir mythique de leur lanceur pour cr&#233;er des effets magiques plus puissants : une boule de feu mythique met le feu aux cr&#233;atures affect&#233;es, une armure de mage mythique peut annuler les coups critiques, etc. Ces sorts ne sont pas distincts et le personnage ne les apprend pas comme les autres par le biais de sa classe de lanceur de sorts. Ce sont plut&#244;t les versions impr&#233;gn&#233;es de pouvoir mythique des sorts que le personnage conna&#238;t d&#233;j&#224;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Apprentissage des sorts mythiques&lt;a class=&quot;headeranchor&quot; id=&quot;Apprentissage_des_sorts_mythiques_0&quot; href=&quot;#Apprentissage_des_sorts_mythiques_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Pour apprendre un sort mythique, le personnage doit poss&#233;der l’aptitude de voie universelle &lt;a class=&quot;pagelink&quot; href=&quot;Aptitudes-De-Voie-Universelles-Mythique.html#INCANTATIONMYTHIQUE&quot; title=&quot;Aptitudes de voie universelles Mythique&quot;&gt;incantation mythique&lt;/a&gt; ou le don &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances-Magiques-Mythiques-(Mythique).html&quot; title=&quot;Connaissances magiques mythiques (mythique)&quot;&gt;Connaissances magiques mythiques&lt;/a&gt;. D&#232;s lors, le personnage d&#233;couvre la m&#233;thode secr&#232;te pour manipuler son pouvoir mythique de fa&#231;on &#224; augmenter l’intensit&#233; des sorts non-mythiques de son choix.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Incantation des sorts mythiques&lt;a class=&quot;headeranchor&quot; id=&quot;Incantation_des_sorts_mythiques_1&quot; href=&quot;#Incantation_des_sorts_mythiques_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Si le personnage connait la version mythique d’un sort, &#224; chaque fois qu’il lance sa version classique, il peut d&#233;penser une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; pour lancer la version mythique &#224; la place. Ceci ne modifie pas le niveau de l’emplacement du sort utilis&#233; pour le lancer.&lt;br /&gt;&lt;br /&gt;Si le personnage pr&#233;pare ses sorts (comme un &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tre&lt;/a&gt; ou un &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt;), il n’a jamais besoin de pr&#233;parer leur version mythique ; s’il pr&#233;pare la version non-mythique d’un sort, il peut lancer sa version mythique en d&#233;pensant une utilisation de pouvoir mythique. Sauf pr&#233;cision contraire, l’incantation de la version mythique d’un sort ne prend pas plus de temps que celle de son &#233;quivalent non-mythique.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Effets des sorts mythiques&lt;a class=&quot;headeranchor&quot; id=&quot;Effets_des_sorts_mythiques_2&quot; href=&quot;#Effets_des_sorts_mythiques_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Sauf indication contraire, un sort mythique fonctionne de la m&#234;me fa&#231;on que sa version classique. Par exemple, les &lt;a class=&quot;pagelink&quot; href=&quot;Zombi-Humain.html&quot; title=&quot;Zombi, Zombi humain&quot;&gt;zombis&lt;/a&gt; cr&#233;&#233;s par les sorts &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animation-Des-Morts.html&quot; title=&quot;Animation des morts&quot;&gt;animation des morts&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;animation des morts mythique&lt;/i&gt; comptent dans la limite maximale de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; de morts-vivants que le personnage peut contr&#244;ler en m&#234;me temps. De la m&#234;me fa&#231;on, une cr&#233;ature Chaotique est immunis&#233;e au &lt;i&gt;marteau du Chaos mythique&lt;/i&gt; tout comme elle est immunis&#233;e au &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marteau-Du-Chaos.html&quot; title=&quot;Marteau du chaos&quot;&gt;marteau du Chaos&lt;/a&gt;&lt;/i&gt; classique.&lt;br /&gt;&lt;br /&gt;&#192; moins que la description d’un sort mythique ne pr&#233;cise le renfort, le remplacement ou l’augmentation d’un effet normalement produit par sa version non-mythique ou qu’un effet en remplace un autre, le sort non-mythique produit tous ses effets en plus de ceux cr&#233;&#233;s par la version mythique. Par exemple, le sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Blasph&#232;me.html&quot; title=&quot;Blasph&#232;me&quot;&gt;blasph&#232;me mythique&lt;/a&gt;&lt;/i&gt; inflige des malus aux cr&#233;atures qui ratent leur &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; ; comme la description du sort ne pr&#233;cise pas que ces malus remplacent ceux inflig&#233;s par sa version non-mythique, ces malus viennent en plus des effets produits par le sort classique.&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;AMPLIFIE&quot; href=&quot;#AMPLIFIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Sorts mythiques amplifi&#233;s&lt;a class=&quot;headeranchor&quot; id=&quot;Sorts_mythiques_amplifi&#233;s_3&quot; href=&quot;#Sorts_mythiques_amplifi&#233;s_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La version amplifi&#233;e d’un sort mythique produit le m&#234;me effet que sa version mythique, en plus d’avantages, d’options ou d’effets augment&#233;s suppl&#233;mentaires. Pour lancer certains sorts mythiques amplifi&#233;s, le personnage doit parfois avoir un &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade&lt;/a&gt; minimum. Le cas &#233;ch&#233;ant, la condition en mati&#232;re de grade associ&#233; aux effets amplifi&#233;s est indiqu&#233;e entre parenth&#232;ses dans la ligne correspondante. Par exemple, &#171; Amplification (4&#232;me) &#187; signifie que le personnage doit avoir atteint le 4&#232;me grade au moins pour utiliser cette option. Si un personnage connait un sort mythique, il sait automatiquement comment lancer sa version amplifi&#233;e lorsqu’il atteint le grade appropri&#233;.&lt;br /&gt;&lt;br /&gt;L’incantation de la version amplifi&#233;e d’un sort mythique exige une d&#233;pense d’utilisations suppl&#233;mentaires de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; au moment de l’incantation. Le nombre d’utilisations suppl&#233;mentaires n&#233;cessaires pour lancer la version amplifi&#233;e d’un sort est indiqu&#233; dans la description Amplifi&#233;e du sort et inclut l’utilisation de pouvoir mythique initialement n&#233;cessaire pour lancer la version mythique du sort. Lorsqu’il lance un sort, le personnage doit d&#233;cider s’il souhaite lancer la version non-mythique, la version mythique ou la version mythique amplifi&#233;e, et d&#233;penser le nombre appropri&#233; d’utilisations de pouvoir mythique. Il ne peut lancer la version non-mythique d’un sort puis d&#233;penser ult&#233;rieurement une utilisation de pouvoir mythique pour le convertir dans sa version mythique. De m&#234;me, il ne peut lancer la version mythique de base d’un sort puis d&#233;penser plus tard la diff&#233;rence d’utilisations de pouvoir mythique pour convertir le sort dans sa version amplifi&#233;e.
&lt;ul&gt;&lt;li&gt;&lt;i&gt;Exemple.&lt;/i&gt; le personnage est un &lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;magicien&lt;/a&gt; niveau 9/&lt;a class=&quot;pagelink&quot; href=&quot;Archimage-Mythique.html&quot; title=&quot;L&amp;#39;archimage mythique&quot;&gt;archimage&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade&lt;/a&gt; 6 qui connait animation mythique des morts et a pr&#233;par&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animation-Des-Morts.html&quot; title=&quot;Animation des morts&quot;&gt;animation des morts&lt;/a&gt;&lt;/i&gt;. L’incantation d’&lt;i&gt;animation des morts&lt;/i&gt; se d&#233;roule comme &#224; l’accoutum&#233;e et ne n&#233;cessite pas de d&#233;pense de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;. L’incantation d’&lt;i&gt;animation des morts mythique&lt;/i&gt; n&#233;cessite la d&#233;pense d’une utilisation de pouvoir mythique lorsque le personnage lance le sort pr&#233;par&#233; d’&lt;i&gt;animation des morts&lt;/i&gt;. L’incantation de la version amplifi&#233;e d’animation mythique des morts n&#233;cessite la d&#233;pense de deux (et non trois) utilisations de pouvoir mythique lorsque le personnage lance son sort pr&#233;par&#233; d’&lt;i&gt;animation des morts&lt;/i&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Les sorts mythiques dans les objets magiques&lt;a class=&quot;headeranchor&quot; id=&quot;Les_sorts_mythiques_dans_les_objets_magiques_4&quot; href=&quot;#Les_sorts_mythiques_dans_les_objets_magiques_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les sorts mythiques ne peuvent &#234;tre int&#233;gr&#233;s dans la fabrication d’objets magiques &#224; moins que l’objet en question ne soit un artefact (il est par exemple impossible de pr&#233;parer une &lt;i&gt;potion de &lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers mythique&lt;/a&gt;&lt;/i&gt;).&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Les sorts mythiques dans le profil des cr&#233;atures&lt;a class=&quot;headeranchor&quot; id=&quot;Les_sorts_mythiques_dans_le_profil_des_cr&#233;atures_5&quot; href=&quot;#Les_sorts_mythiques_dans_le_profil_des_cr&#233;atures_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Dans le profil d’une cr&#233;ature, l’exposant &#171; M &#187; indique que la cr&#233;ature connait la version mythique du sort.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sort p&#233;n&#233;trant&lt;a class=&quot;headeranchor&quot; id=&quot;Sort_p&#233;n&#233;trant_6&quot; href=&quot;#Sort_p&#233;n&#233;trant_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Lorsque le personnage lance un sort mythique, il peut &#233;galement lancer la forme p&#233;n&#233;trante de ce sort pour augmenter les chances de succomber &#224; ses effets. En d&#233;pensant une utilisation suppl&#233;mentaire de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, le personnage augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; du sort de +2 et b&#233;n&#233;ficie d’un bonus de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; pour ignorer les &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-&#192;-La-Magie-(Capacit&#233;).html&quot; title=&quot;RM&quot;&gt;r&#233;sistances &#224; la magie&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Sort r&#233;sistant&lt;a class=&quot;headeranchor&quot; id=&quot;Sort_r&#233;sistant_7&quot; href=&quot;#Sort_r&#233;sistant_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Lorsque le personnage lance un sort mythique, il peut &#233;galement lancer sa forme r&#233;sistante pour diminuer les risques de le voir dissip&#233; ou contr&#233;. Cela n&#233;cessite la d&#233;pense d’une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; ; le cas &#233;ch&#233;ant, les tests effectu&#233;s pour dissiper le sort subissent un malus de -4 et le sort ne peut &#234;tre contr&#233; &#224; moins que le lanceur adverse d&#233;pense &#233;galement une utilisation de pouvoir mythique pour ignorer la r&#233;sistante du sort lanc&#233; par le personnage (dans ce cas, les r&#232;gles sur la mani&#232;re de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Contresort.html&quot; title=&quot;contresort&quot;&gt;contrer un sort&lt;/a&gt; s’appliquent normalement).&lt;br /&gt;&lt;br /&gt;Le personnage peut combiner les formes r&#233;sistantes et p&#233;n&#233;trantes d’un sort ; le cas &#233;ch&#233;ant, il doit d&#233;penser un total de deux utilisations de pouvoir mythique suppl&#233;mentaires. Il peut lancer les formes r&#233;sistantes et p&#233;n&#233;trantes des sorts mythiques amplifi&#233;s de la m&#234;me fa&#231;on.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Les grades dans la description des sorts mythiques&lt;a class=&quot;headeranchor&quot; id=&quot;Les_grades_dans_la_description_des_sorts_mythiques_8&quot; href=&quot;#Les_grades_dans_la_description_des_sorts_mythiques_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&#192; moins que le contraire ne soit indiqu&#233;, toutes les indications de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade&lt;/a&gt; dans la description des sorts mythiques se r&#233;f&#232;rent au grade de la cr&#233;ature qui lance le sort. Chaque fois que la description d’un sort mythique indique la moiti&#233; du grade du personnage, le r&#233;sultat est de 1 au minimum (ce qui signifie qu’un personnage de grade 1 obtient tout de m&#234;me un avantage).&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Liste des sorts mythiques&lt;a class=&quot;headeranchor&quot; id=&quot;Liste_des_sorts_mythiques_19&quot; href=&quot;#Liste_des_sorts_mythiques_19&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les listes suivantes compilent la totalit&#233; des versions mythiques des sorts existants pr&#233;sent&#233;s dans cet ouvrage, ainsi que les nouveaux sorts qui font usage, conf&#232;rent ou volent du pouvoir mythique.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Ordre de pr&#233;sentation.&lt;/b&gt; Dans les listes de sorts et la br&#232;ve description qui suit le nom de chacun d’entre eux, les sorts sont tri&#233;s dans l’ordre alphab&#233;tique de leur nom, &#224; l’exception de ceux qui font partie d’une cha&#238;ne de sorts particuliers.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;D&#233;s de Vie.&lt;/b&gt; Le terme &#171; d&#233;s de vie &#187; est un synonyme de &#171; niveaux du personnage &#187; dans le cadre des effets affectant un nombre sp&#233;cifique de D&#233;s de Vie de cr&#233;atures.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Niveau de lanceur de sorts. &lt;/b&gt;La puissance d’un sort se mesure au niveau de celui qui le lance. Elle est d&#233;finie par le niveau de classe du lanceur de sorts dans le cadre de l’incantation d’un sort particulier.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Cr&#233;atures et personnages.&lt;/b&gt; Les termes &#171; cr&#233;ature &#187; et &#171; personnage &#187; sont synonymes dans la description des sorts.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Nouveaux sorts.&lt;/b&gt; Un ast&#233;risque (*) apr&#232;s le nom d’un sort indique que ce sort est nouveau et que sa description se trouve dans cette section.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Sorts mythiques amplifi&#233;s.&lt;/b&gt; Un exposant &#171; A &#187; apparait apr&#232;s le nom d’un sort dans ces listes lorsque le sort en question dispose d’un effet amplifi&#233; si son lanceur d&#233;cide de d&#233;penser des utilisations suppl&#233;mentaires de pouvoir mythique. Voir la description des sorts concern&#233;s pour plus d’informations sur leurs effets amplifi&#233;s.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Formules mythiques d’alchimiste&lt;a class=&quot;headeranchor&quot; id=&quot;Formules_mythiques_d’alchimiste_9&quot; href=&quot;#Formules_mythiques_d’alchimiste_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;b&gt;Formules mythiques d’alchimiste de 1er niveau.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Agrandissement.html&quot; title=&quot;Agrandissement&quot;&gt;Agrandissement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Anticipation-Du-Danger.html&quot; title=&quot;Anticipation du danger&quot;&gt;anticipation du danger&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Coup-Au-But.html&quot; title=&quot;Coup au but&quot;&gt;coup au but&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Endurance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;Endurance aux &#233;nergies destructives&quot;&gt;endurance aux &#233;nergies destructives&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Rapetissement.html&quot; title=&quot;Rapetissement&quot;&gt;rapetissement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Repli-Exp&#233;ditif.html&quot; title=&quot;Repli exp&#233;ditif&quot;&gt;repli exp&#233;ditif&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Soins-L&#233;gers.html&quot; title=&quot;Soins l&#233;gers&quot;&gt;soins l&#233;gers&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Formules mythiques d’alchimiste de 2&#232;me niveau.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Aspect-Animal.html&quot; title=&quot;Aspect animal&quot;&gt;Aspect animal&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Barri&#232;re-Protectrice.html&quot; title=&quot;Barri&#232;re protectrice&quot;&gt;barri&#232;re protectrice&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Injection.html&quot; title=&quot;Injection&quot;&gt;injection&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Invective-Cuisante.html&quot; title=&quot;Invective cuisante&quot;&gt;invective cuisante&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;L&#233;vitation.html&quot; title=&quot;L&#233;vitation&quot;&gt;l&#233;vitation&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pattes-Daraign&#233;e.html&quot; title=&quot;Pattes d&amp;#39;araign&#233;e&quot;&gt;pattes d&#39;araign&#233;e&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Peau-D&#233;corce.html&quot; title=&quot;Peau d&amp;#39;&#233;corce&quot;&gt;peau d&#39;&#233;corce&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Les-Projectiles.html&quot; title=&quot;Protection contre les projectiles&quot;&gt;protection contre les projectiles&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Simulacre-De-Vie.html&quot; title=&quot;Simulacre de vie&quot;&gt;simulacre de vie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Soins-Mod&#233;r&#233;s.html&quot; title=&quot;Soins mod&#233;r&#233;s&quot;&gt;soins mod&#233;r&#233;s&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Formules mythiques d’alchimiste de 3&#232;me niveau.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Creusement.html&quot; title=&quot;Creusement&quot;&gt;Creusement&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tat-Gazeux.html&quot; title=&quot;&#201;tat gazeux&quot;&gt;&#233;tat gazeux&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-I.html&quot; title=&quot;Forme bestiale I&quot;&gt;forme bestiale I&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;H&#233;ro&#239;sme.html&quot; title=&quot;H&#233;ro&#239;sme&quot;&gt;h&#233;ro&#239;sme&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Jumeau-De-Vomi.html&quot; title=&quot;Jumeau de vomi&quot;&gt;jumeau de vomi&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Physique-Monstrueux-I.html&quot; title=&quot;Physique monstrueux I&quot;&gt;physique monstrueux I&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Rapidit&#233;.html&quot; title=&quot;Rapidit&#233;&quot;&gt;rapidit&#233;&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;servoir-Draconique.html&quot; title=&quot;R&#233;servoir draconique&quot;&gt;r&#233;servoir draconique&lt;/a&gt;&lt;sup&gt;A&lt;/sup&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Soins-Importants.html&quot; title=&quot;Soins importants&quot;&gt;soins importants&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; hr